import numpy as np
def solve(X):
    X = np.asarray(X, dtype=float)
    if X.ndim != 2 or X.shape[0] < 2:
        raise ValueError("cần ma trận 2D có ít nhất hai mẫu")
    centered = X - X.mean(axis=0)
    return centered.T @ centered / (X.shape[0] - 1)

